27.       throw new RangeError(`percent must be between 0 and 100 (got ${percent})`);
28.     }
29.   }
30. 
31.   computeDiscountCents(subtotalCents: number): number {
32.     if (subtotalCents <= 0) return 0;
33.     return Math.floor((subtotalCents * this.percent) / 100);
34.   }
35. }
