describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects bracket with upToGrams <= 0", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 100 }],
            5.5,
          ),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 100 }],
            -1,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 2000, costCents: 600 },
      { upToGrams: 5000, costCents: 1200 },
    ]);

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 10000)).toBe(0);
    });

    it("returns 0 when total weight is 0 (no weightGrams)", () => {
      expect(calc.computeShippingCents([lineNoWeight()], 10000)).toBe(0);
    });

    it("selects first bracket when weight is at boundary", () => {
      expect(calc.computeShippingCents([line(500)], 10000)).toBe(300);
    });

    it("selects first bracket when weight is below boundary", () => {
      expect(calc.computeShippingCents([line(200)], 10000)).toBe(300);
    });

    it("selects second bracket when weight exceeds first boundary", () => {
      expect(calc.computeShippingCents([line(501)], 10000)).toBe(600);
    });

    it("selects second bracket at its upper boundary", () => {
      expect(calc.computeShippingCents([line(2000)], 10000)).toBe(600);
    });

    it("selects third bracket for weight above second", () => {
      expect(calc.computeShippingCents([line(2001)], 10000)).toBe(1200);
    });

    it("uses heaviest bracket cost as overflow when no overflowCostCents set", () => {
      expect(calc.computeShippingCents([line(9999)], 10000)).toBe(1200);
    });

    it("uses overflowCostCents when weight exceeds all brackets", () => {
      const calcWithOverflow = new WeightBasedShippingCalculator(
        [
          { upToGrams: 500, costCents: 300 },
          { upToGrams: 2000, costCents: 600 },
        ],
        2000,
      );
      expect(calcWithOverflow.computeShippingCents([line(3000)], 10000)).toBe(2000);
    });

    it("sorts brackets regardless of input order", () => {
      const unordered = new WeightBasedShippingCalculator([
        { upToGrams: 5000, costCents: 1200 },
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 600 },
      ]);
      expect(unordered.computeShippingCents([line(400)], 10000)).toBe(300);
    });

    it("sums weight across multiple lines", () => {
      // 2 items at 300g each = 600g → second bracket
      expect(calc.computeShippingCents([line(300, 2)], 10000)).toBe(600);
    });
  });
});

