import { describe, it, expect } from "vitest";
import { Cart } from "../src/cart.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";

const product = (id: string, price: number, weight?: number): Product => ({
  id,
  name: `Product ${id}`,
  unitPriceCents: price,
  weightGrams: weight,
});

describe("Cart", () => {
  describe("add", () => {
    it("adds a product to the cart", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);
      expect(cart.itemCount).toBe(2);
    });

    it("merges quantity when adding same product again", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);
      cart.add(product("a", 1000), 3);
      expect(cart.itemCount).toBe(5);
    });

    it("rejects quantity <= 0", () => {
      const cart = new Cart();
      expect(() => cart.add(product("a", 1000), 0)).toThrow(RangeError);
      expect(() => cart.add(product("a", 1000), -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(product("a", 1000), 1.5)).toThrow(RangeError);
    });

    it("rejects negative unitPriceCents", () => {
      const cart = new Cart();
      expect(() => cart.add(product("a", -1), 1)).toThrow(RangeError);
    });
  });

  describe("remove", () => {
    it("removes an existing product and returns true", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      expect(cart.remove("a")).toBe(true);
      expect(cart.itemCount).toBe(0);
    });

    it("returns false for unknown product id", () => {
      const cart = new Cart();
      expect(cart.remove("nonexistent")).toBe(false);
    });
  });

  describe("updateQuantity", () => {
    it("updates quantity of existing product", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 3);
      cart.updateQuantity("a", 5);
      expect(cart.itemCount).toBe(5);
    });

    it("removes product when quantity is set to 0", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 3);
      cart.updateQuantity("a", 0);
      expect(cart.itemCount).toBe(0);
    });

    it("throws for unknown product", () => {
      const cart = new Cart();
      expect(() => cart.updateQuantity("unknown", 5)).toThrow(
        "Product unknown is not in the cart",
      );
    });

    it("throws for negative quantity", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
    });

    it("throws for non-integer quantity", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      expect(() => cart.updateQuantity("a", 2.5)).toThrow(RangeError);
    });
  });

  describe("clear", () => {
    it("removes all items", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);
      cart.add(product("b", 2000), 1);
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });
  });

  describe("snapshot", () => {
    it("returns a deep copy that does not affect cart state", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);
      const snap = cart.snapshot();
      (snap as any)[0].quantity = 99;
      expect(cart.itemCount).toBe(2);
    });
  });

  describe("totals (pricing pipeline)", () => {
    it("computes subtotal as sum of price * quantity", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);
      cart.add(product("b", 500), 3);
      const totals = cart.totals();
      expect(totals.subtotalCents).toBe(3500);
    });

    it("applies discount, then tax on discounted subtotal, then shipping", () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: () => 500,
      };
      const tax: TaxCalculator = {
        computeTaxCents: (taxable) => Math.floor(taxable * 0.1),
      };
      const shipping: ShippingCalculator = {
        computeShippingCents: () => 200,
      };
      const cart = new Cart({
        discountPolicy: discount,
        taxCalculator: tax,
        shippingCalculator: shipping,
      });
      cart.add(product("a", 1000), 3); // subtotal = 3000
      const totals = cart.totals();
      expect(totals.subtotalCents).toBe(3000);
      expect(totals.discountCents).toBe(500);
      // Tax on (3000 - 500) = 2500 * 0.1 = 250
      expect(totals.taxCents).toBe(250);
      expect(totals.shippingCents).toBe(200);
      // total = 2500 + 250 + 200 = 2950
      expect(totals.totalCents).toBe(2950);
    });

    it("clamps discount to [0, subtotal]", () => {
      const overDiscount: DiscountPolicy = {
        computeDiscountCents: () => 99999,
      };
      const cart = new Cart({ discountPolicy: overDiscount });
      cart.add(product("a", 1000), 1);
      const totals = cart.totals();
      expect(totals.discountCents).toBe(1000);
      expect(totals.totalCents).toBe(0);
    });

    it("clamps negative discount to 0", () => {
      const negativeDiscount: DiscountPolicy = {
        computeDiscountCents: () => -500,
      };
      const cart = new Cart({ discountPolicy: negativeDiscount });
      cart.add(product("a", 1000), 1);
      const totals = cart.totals();
      expect(totals.discountCents).toBe(0);
    });

    it("clamps negative tax to 0", () => {
      const negativeTax: TaxCalculator = {
        computeTaxCents: () => -100,
      };
      const cart = new Cart({ taxCalculator: negativeTax });
      cart.add(product("a", 1000), 1);
      expect(cart.totals().taxCents).toBe(0);
    });

    it("clamps negative shipping to 0", () => {
      const negativeShipping: ShippingCalculator = {
        computeShippingCents: () => -100,
      };
      const cart = new Cart({ shippingCalculator: negativeShipping });
      cart.add(product("a", 1000), 1);
      expect(cart.totals().shippingCents).toBe(0);
    });

    it("empty cart has all zeros", () => {
      const cart = new Cart();
      const totals = cart.totals();
      expect(totals.subtotalCents).toBe(0);
      expect(totals.discountCents).toBe(0);
      expect(totals.taxCents).toBe(0);
      expect(totals.shippingCents).toBe(0);
      expect(totals.totalCents).toBe(0);
    });

    it("uses defaults when no config provided", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      const totals = cart.totals();
      // NoDiscount, NoTax, FreeShipping
      expect(totals.discountCents).toBe(0);
      expect(totals.taxCents).toBe(0);
      expect(totals.shippingCents).toBe(0);
      expect(totals.totalCents).toBe(1000);
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import { InventoryError, type PriceFetcher, type InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import type { Product } from "../src/product.ts";
import { PercentageDiscountPolicy } from "../src/pricing.ts";
import { FlatShippingCalculator } from "../src/shipping.ts";

const product = (id: string, price: number): Product => ({
  id,
  name: `Product ${id}`,
  unitPriceCents: price,
});

describe("Cart.checkout()", () => {
  describe("without collaborators", () => {
    it("returns totals and lines snapshot", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(2000);
      expect(result.lines).toHaveLength(1);
      expect(result.lines[0].product.id).toBe("a");
    });
  });

  describe("with PriceFetcher", () => {
    it("refreshes prices before computing totals", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(2000),
      };
      const result = await cart.checkout({ priceFetcher: fetcher });
      expect(result.totals.subtotalCents).toBe(2000);
      expect(result.lines[0].product.unitPriceCents).toBe(2000);
    });

    it("propagates fetcher failure", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockRejectedValue(new Error("timeout")),
      };
      await expect(cart.checkout({ priceFetcher: fetcher })).rejects.toThrow("timeout");
    });
  });

  describe("with InventoryChecker", () => {
    it("passes when inventory is available", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
      };
      const result = await cart.checkout({ inventoryChecker: checker });
      expect(result.totals.subtotalCents).toBe(2000);
      expect(checker.check).toHaveBeenCalledWith("a", 2);
    });

    it("throws InventoryError when not available", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 5);
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          availableQuantity: 2,
          reason: "low stock",
        }),
      };
      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.productId).toBe("a");
        expect(invErr.requested).toBe(5);
        expect(invErr.available).toBe(2);
        expect(invErr.message).toBe("low stock");
      }
    });

    it("throws InventoryError on partial-stock denial (available but insufficient quantity)", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 10);
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 3,
        }),
      };
      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.productId).toBe("a");
        expect(invErr.requested).toBe(10);
        expect(invErr.available).toBe(3);
      }
    });

    it("checks inventory for all lines and fails on first denial", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      cart.add(product("b", 2000), 1);
      const checker: InventoryChecker = {
        check: vi.fn()
          .mockResolvedValueOnce({ available: true, availableQuantity: 100 })
          .mockResolvedValueOnce({ available: false }),
      };
      await expect(cart.checkout({ inventoryChecker: checker })).rejects.toThrow(InventoryError);
      expect(checker.check).toHaveBeenCalledTimes(2);
    });
  });

  describe("with AsyncTaxRateProvider", () => {
    it("uses async tax calculator for totals", async () => {
      const cart = new Cart({ region: "US-CA" });
      cart.add(product("a", 10000), 1);
      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const result = await cart.checkout({ asyncTaxProvider: provider });
      expect(result.totals.taxCents).toBe(1000); // 10% of 10000
      expect(provider.getRate).toHaveBeenCalledWith("US-CA");
    });

    it("applies discount before async tax", async () => {
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(20),
        region: "US",
      });
      cart.add(product("a", 10000), 1);
      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const result = await cart.checkout({ asyncTaxProvider: provider });
      // Subtotal 10000, discount 20% = 2000, taxable = 8000, tax 10% = 800
      expect(result.totals.discountCents).toBe(2000);
      expect(result.totals.taxCents).toBe(800);
    });

    it("includes shipping in async totals path", async () => {
      const cart = new Cart({
        shippingCalculator: new FlatShippingCalculator(500),
        region: "US",
      });
      cart.add(product("a", 10000), 1);
      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.05),
      };
      const result = await cart.checkout({ asyncTaxProvider: provider });
      // Tax = 5% of 10000 = 500, shipping = 500
      expect(result.totals.taxCents).toBe(500);
      expect(result.totals.shippingCents).toBe(500);
      expect(result.totals.totalCents).toBe(11000);
    });

    it("propagates async tax provider failure", async () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("rate service down")),
      };
      await expect(cart.checkout({ asyncTaxProvider: provider })).rejects.toThrow(
        "rate service down",
      );
    });
  });

  describe("combined collaborators", () => {
    it("runs full pipeline: price refresh → inventory check → async tax", async () => {
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(10),
        shippingCalculator: new FlatShippingCalculator(300),
        region: "FR",
      });
      cart.add(product("a", 1000), 2);

      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1500),
      };
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 50 }),
      };
      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.2),
      };

      const result = await cart.checkout({
        priceFetcher: fetcher,
        inventoryChecker: checker,
        asyncTaxProvider: provider,
      });

      // Refreshed price: 1500 * 2 = 3000
      expect(result.totals.subtotalCents).toBe(3000);
      // Discount: 10% of 3000 = 300
      expect(result.totals.discountCents).toBe(300);
      // Tax: 20% of (3000 - 300) = 20% of 2700 = 540
      expect(result.totals.taxCents).toBe(540);
      // Shipping: flat 300
      expect(result.totals.shippingCents).toBe(300);
      // Total: 2700 + 540 + 300 = 3540
      expect(result.totals.totalCents).toBe(3540);

      expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("a");
      expect(checker.check).toHaveBeenCalledWith("a", 2);
      expect(provider.getRate).toHaveBeenCalledWith("FR");
    });
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it("returns 0 for a positive subtotal", () => {
    expect(policy.computeDiscountCents(10000)).toBe(0);
  });

  it("returns 0 for zero subtotal", () => {
    expect(policy.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    expect(policy.computeDiscountCents(-500)).toBe(0);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([
      [-1, "negative"],
      [101, "over 100"],
      [NaN, "NaN"],
      [Infinity, "Infinity"],
    ])("rejects %s (%s)", (percent) => {
      expect(() => new PercentageDiscountPolicy(percent)).toThrow(RangeError);
    });

    it("accepts 0%", () => {
      expect(() => new PercentageDiscountPolicy(0)).not.toThrow();
    });

    it("accepts 100%", () => {
      expect(() => new PercentageDiscountPolicy(100)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("computes 10% of 10000 as 1000", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(10000)).toBe(1000);
    });

    it("rounds down to the nearest cent", () => {
      const policy = new PercentageDiscountPolicy(33);
      // 33% of 100 = 33.0 → 33
      expect(policy.computeDiscountCents(100)).toBe(33);
      // 33% of 101 = 33.33 → 33
      expect(policy.computeDiscountCents(101)).toBe(33);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(-1000)).toBe(0);
    });

    it("100% returns full subtotal", () => {
      const policy = new PercentageDiscountPolicy(100);
      expect(policy.computeDiscountCents(9999)).toBe(9999);
    });

    it("0% returns 0", () => {
      const policy = new PercentageDiscountPolicy(0);
      expect(policy.computeDiscountCents(5000)).toBe(0);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects negative amounts", () => {
      expect(() => new FixedAmountDiscountPolicy(-1)).toThrow(RangeError);
    });

    it("rejects non-integer amounts", () => {
      expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
    });

    it("accepts 0", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("returns the fixed amount when subtotal exceeds it", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(10000)).toBe(500);
    });

    it("caps at subtotal when amount exceeds subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(5000);
      expect(policy.computeDiscountCents(3000)).toBe(3000);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("returns exactly subtotal when amount equals subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(1000);
      expect(policy.computeDiscountCents(1000)).toBe(1000);
    });
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policy list", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all child policies against original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      // 10% of 10000 = 1000, fixed 200 → total 1200
      expect(composite.computeDiscountCents(10000)).toBe(1200);
    });

    it("ignores negative child results (clamps each to 0)", () => {
      const negativePolicy = {
        computeDiscountCents: () => -500,
      };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      expect(composite.computeDiscountCents(1000)).toBe(100);
    });

    it("can exceed subtotal (clamping is caller's job)", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(80), new PercentageDiscountPolicy(80)],
        "sum",
      );
      // 80% + 80% = 160% of subtotal
      expect(composite.computeDiscountCents(1000)).toBe(1600);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "sum",
      );
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially, each on remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new PercentageDiscountPolicy(50)],
        "chain",
      );
      // First: 50% of 1000 = 500, remaining = 500
      // Second: 50% of 500 = 250, remaining = 250
      // Total discount = 750
      expect(composite.computeDiscountCents(1000)).toBe(750);
    });

    it("ordering affects the result", () => {
      const compositeA = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(300), new PercentageDiscountPolicy(50)],
        "chain",
      );
      const compositeB = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new FixedAmountDiscountPolicy(300)],
        "chain",
      );
      // A: fixed 300 off 1000 → remaining 700, then 50% of 700 = 350 → total 650
      // B: 50% of 1000 = 500 → remaining 500, then fixed 300 off 500 → total 800
      expect(compositeA.computeDiscountCents(1000)).toBe(650);
      expect(compositeB.computeDiscountCents(1000)).toBe(800);
    });

    it("stops accumulating when remaining hits 0", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(1000),
          new PercentageDiscountPolicy(50),
        ],
        "chain",
      );
      // Fixed takes entire 1000, remaining = 0, percentage gives 0
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("clamps each child negative result to 0", () => {
      const negativePolicy = { computeDiscountCents: () => -999 };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(100)],
        "chain",
      );
      expect(composite.computeDiscountCents(500)).toBe(100);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });

  it("defaults to sum mode when not specified", () => {
    const composite = new CompositeDiscountPolicy([
      new FixedAmountDiscountPolicy(100),
      new FixedAmountDiscountPolicy(200),
    ]);
    expect(composite.computeDiscountCents(1000)).toBe(300);
  });
});

import { describe, it, expect, vi } from "vitest";
import {
  NoTaxCalculator,
  RegionalTaxCalculator,
  AsyncTaxCalculator,
  totalLineWeightGrams,
  type AsyncTaxRateProvider,
} from "../src/tax.ts";
import type { CartLine } from "../src/product.ts";

describe("NoTaxCalculator", () => {
  const calc = new NoTaxCalculator();

  it("returns 0 regardless of inputs", () => {
    expect(calc.computeTaxCents(10000, "US")).toBe(0);
    expect(calc.computeTaxCents(0, "FR")).toBe(0);
    expect(calc.computeTaxCents(999, "GB")).toBe(0);
  });
});

describe("RegionalTaxCalculator", () => {
  describe("constructor validation", () => {
    it("rejects defaultRate < 0", () => {
      expect(() => new RegionalTaxCalculator({}, -0.01)).toThrow(RangeError);
    });

    it("rejects defaultRate > 1", () => {
      expect(() => new RegionalTaxCalculator({}, 1.01)).toThrow(RangeError);
    });

    it("rejects NaN defaultRate", () => {
      expect(() => new RegionalTaxCalculator({}, NaN)).toThrow(RangeError);
    });

    it("rejects region rate < 0", () => {
      expect(() => new RegionalTaxCalculator({ US: -0.05 })).toThrow(RangeError);
    });

    it("rejects region rate > 1", () => {
      expect(() => new RegionalTaxCalculator({ US: 1.5 })).toThrow(RangeError);
    });

    it("accepts boundary rates 0 and 1", () => {
      expect(() => new RegionalTaxCalculator({ US: 0, FR: 1 }, 0.5)).not.toThrow();
    });
  });

  describe("computeTaxCents", () => {
    const calc = new RegionalTaxCalculator(
      { "US-CA": 0.0875, FR: 0.2 },
      0.05,
    );

    it("uses the matching region rate", () => {
      // 8.75% of 10000 = 875
      expect(calc.computeTaxCents(10000, "US-CA")).toBe(875);
    });

    it("falls back to default rate for unknown regions", () => {
      // 5% of 10000 = 500
      expect(calc.computeTaxCents(10000, "JP")).toBe(500);
    });

    it("rounds down to nearest cent", () => {
      // 20% of 999 = 199.8 → 199
      expect(calc.computeTaxCents(999, "FR")).toBe(199);
    });

    it("returns 0 for zero taxable", () => {
      expect(calc.computeTaxCents(0, "US-CA")).toBe(0);
    });

    it("returns 0 for negative taxable", () => {
      expect(calc.computeTaxCents(-500, "US-CA")).toBe(0);
    });

    it("defaults defaultRate to 0 when not provided", () => {
      const noDefault = new RegionalTaxCalculator({ US: 0.1 });
      expect(noDefault.computeTaxCents(1000, "UNKNOWN")).toBe(0);
    });
  });
});

describe("AsyncTaxCalculator", () => {
  it("resolves tax using provider rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const calc = new AsyncTaxCalculator(provider);
    expect(await calc.computeTaxCents(10000, "US")).toBe(1000);
    expect(provider.getRate).toHaveBeenCalledWith("US");
  });

  it("rounds down to nearest cent", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.0875),
    };
    const calc = new AsyncTaxCalculator(provider);
    // 8.75% of 999 = 87.4125 → 87
    expect(await calc.computeTaxCents(999, "US-CA")).toBe(87);
  });

  it("returns 0 for zero taxable without calling provider", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const calc = new AsyncTaxCalculator(provider);
    expect(await calc.computeTaxCents(0, "US")).toBe(0);
    expect(provider.getRate).not.toHaveBeenCalled();
  });

  it("returns 0 for negative taxable without calling provider", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const calc = new AsyncTaxCalculator(provider);
    expect(await calc.computeTaxCents(-100, "US")).toBe(0);
    expect(provider.getRate).not.toHaveBeenCalled();
  });

  it("throws RangeError for rate > 1", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(1.5),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("throws RangeError for rate < 0", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(-0.1),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("throws RangeError for NaN rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(NaN),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("propagates provider rejection", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("network failure")),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow("network failure");
  });
});

describe("totalLineWeightGrams", () => {
  it("sums weight * quantity across lines", () => {
    const lines: CartLine[] = [
      { product: { id: "a", name: "A", unitPriceCents: 100, weightGrams: 500 }, quantity: 2 },
      { product: { id: "b", name: "B", unitPriceCents: 200, weightGrams: 300 }, quantity: 3 },
    ];
    expect(totalLineWeightGrams(lines)).toBe(1900); // 1000 + 900
  });

  it("treats missing weightGrams as 0", () => {
    const lines: CartLine[] = [
      { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 5 },
    ];
    expect(totalLineWeightGrams(lines)).toBe(0);
  });

  it("returns 0 for empty lines", () => {
    expect(totalLineWeightGrams([])).toBe(0);
  });
});

import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

const line = (weightGrams: number, quantity = 1): CartLine => ({
  product: { id: "p1", name: "Product", unitPriceCents: 1000, weightGrams },
  quantity,
});

const lineNoWeight = (quantity = 1): CartLine => ({
  product: { id: "p1", name: "Product", unitPriceCents: 1000 },
  quantity,
});

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("always returns 0", () => {
    expect(calc.computeShippingCents([line(500)], 10000)).toBe(0);
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects negative flatCents", () => {
      expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
    });

    it("rejects non-integer flatCents", () => {
      expect(() => new FlatShippingCalculator(5.5)).toThrow(RangeError);
    });

    it("rejects negative freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
    });

    it("rejects non-integer freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 99.9)).toThrow(RangeError);
    });

    it("accepts 0 flatCents", () => {
      expect(() => new FlatShippingCalculator(0)).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    it("returns flat fee for non-empty cart", () => {
      const calc = new FlatShippingCalculator(599);
      expect(calc.computeShippingCents([line(100)], 5000)).toBe(599);
    });

    it("returns 0 for empty cart", () => {
      const calc = new FlatShippingCalculator(599);
      expect(calc.computeShippingCents([], 5000)).toBe(0);
    });

    it("returns 0 when subtotal meets freeOver threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([line(100)], 5000)).toBe(0);
    });

    it("returns 0 when subtotal exceeds freeOver threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([line(100)], 6000)).toBe(0);
    });

    it("returns flat fee when subtotal is below freeOver threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([line(100)], 4999)).toBe(599);
    });
  });
});

describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects bracket with upToGrams <= 0", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 100 }],
            5.5,
          ),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 100 }],
            -1,
          ),
