    it("can exceed subtotal (clamping is caller's job)", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(80), new PercentageDiscountPolicy(80)],
        "sum",
      );
      // 80% + 80% = 160% of subtotal
      expect(composite.computeDiscountCents(1000)).toBe(1600);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "sum",
      );
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially, each on remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new PercentageDiscountPolicy(50)],
        "chain",
      );
      // First: 50% of 1000 = 500, remaining = 500
      // Second: 50% of 500 = 250, remaining = 250
      // Total discount = 750
      expect(composite.computeDiscountCents(1000)).toBe(750);
    });

    it("ordering affects the result", () => {
      const compositeA = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(300), new PercentageDiscountPolicy(50)],
        "chain",
      );
      const compositeB = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new FixedAmountDiscountPolicy(300)],
        "chain",
      );
      // A: fixed 300 off 1000 → remaining 700, then 50% of 700 = 350 → total 650
      // B: 50% of 1000 = 500 → remaining 500, then fixed 300 off 500 → total 800
      expect(compositeA.computeDiscountCents(1000)).toBe(650);
      expect(compositeB.computeDiscountCents(1000)).toBe(800);
    });

    it("stops accumulating when remaining hits 0", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(1000),
          new PercentageDiscountPolicy(50),
        ],
        "chain",
      );
      // Fixed takes entire 1000, remaining = 0, percentage gives 0
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("clamps each child negative result to 0", () => {
      const negativePolicy = { computeDiscountCents: () => -999 };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(100)],
        "chain",
      );
      expect(composite.computeDiscountCents(500)).toBe(100);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });

  it("defaults to sum mode when not specified", () => {
    const composite = new CompositeDiscountPolicy([
      new FixedAmountDiscountPolicy(100),
      new FixedAmountDiscountPolicy(200),
    ]);
    expect(composite.computeDiscountCents(1000)).toBe(300);
  });
});
"}

