import { Cart } from "../src/cart.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";

const product = (id: string, price: number, weight?: number): Product => ({
  id,
  name: `Product ${id}`,
  unitPriceCents: price,
  weightGrams: weight,
});

describe("Cart", () => {
  describe("add", () => {
    it("adds a product to the cart", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);
      expect(cart.itemCount).toBe(2);
    });

    it("merges quantity when adding same product again", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);
      cart.add(product("a", 1000), 3);
      expect(cart.itemCount).toBe(5);
    });

    it("rejects quantity <= 0", () => {
      const cart = new Cart();
      expect(() => cart.add(product("a", 1000), 0)).toThrow(RangeError);
      expect(() => cart.add(product("a", 1000), -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(product("a", 1000), 1.5)).toThrow(RangeError);
    });

    it("rejects negative unitPriceCents", () => {
      const cart = new Cart();
      expect(() => cart.add(product("a", -1), 1)).toThrow(RangeError);
    });
  });

  describe("remove", () => {
    it("removes an existing product and returns true", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      expect(cart.remove("a")).toBe(true);
      expect(cart.itemCount).toBe(0);
    });

    it("returns false for unknown product id", () => {
      const cart = new Cart();
      expect(cart.remove("nonexistent")).toBe(false);
    });
  });

  describe("updateQuantity", () => {
    it("updates quantity of existing product", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 3);
      cart.updateQuantity("a", 5);
      expect(cart.itemCount).toBe(5);
    });

    it("removes product when quantity is set to 0", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 3);
      cart.updateQuantity("a", 0);
      expect(cart.itemCount).toBe(0);
    });

    it("throws for unknown product", () => {
      const cart = new Cart();
      expect(() => cart.updateQuantity("unknown", 5)).toThrow(
        "Product unknown is not in the cart",
      );
    });

    it("throws for negative quantity", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
    });

    it("throws for non-integer quantity", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 1);
      expect(() => cart.updateQuantity("a", 2.5)).toThrow(RangeError);
    });
  });

  describe("clear", () => {
    it("removes all items", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);
      cart.add(product("b", 2000), 1);
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });
  });

  describe("snapshot", () => {
    it("returns a deep copy that does not affect cart state", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);
      const snap = cart.snapshot();
      (snap as any)[0].quantity = 99;
      expect(cart.itemCount).toBe(2);
    });
  });

  describe("totals (pricing pipeline)", () => {
    it("computes subtotal as sum of price * quantity", () => {
      const cart = new Cart();
      cart.add(product("a", 1000), 2);
      cart.add(product("b", 500), 3);
      const totals = cart.totals();
      expect(totals.subtotalCents).toBe(3500);
    });

    it("applies discount, then tax on discounted subtotal, then shipping", () => {
      const discount: DiscountPolicy = {
        computeDiscountCents: () => 500,
      };
      const tax: TaxCalculator = {
        computeTaxCents: (taxable) => Math.floor(taxable * 0.1),
      };
      const shipping: ShippingCalculator = {
        computeShippingCents: () => 200,
      };
      const cart = new Cart({
        discountPolicy: discount,
        taxCalculator: tax,
        shippingCalculator: shipping,
      });
      cart.add(product("a", 1000), 3); // subtotal = 3000
      const totals = cart.totals();
      expect(totals.subtotalCents).toBe(3000);
      expect(totals.discountCents).toBe(500);
      // Tax on (3000 - 500) = 2500 * 0.1 = 250
      expect(totals.taxCents).toBe(250);
      expect(totals.shippingCents).toBe(200);
      // total = 2500 + 250 + 200 = 2950
      expect(totals.totalCents).toBe(2950);
    });

    it("clamps discount to [0, subtotal]", () => {
      const overDiscount: DiscountPolicy = {
        computeDiscountCents: () => 99999,
      };
      const cart = new Cart({ discountPolicy: overDiscount });
      cart.add(product("a", 1000), 1);
      const totals = cart.totals();
      expect(totals.discountCents).toBe(1000);
      expect(totals.totalCents).toBe(0);
